import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const checked = '2026-09-03';

const s = (id,label,url,note) => ({id,label,url,note});
const n = (id,name,parent,lineage,note,hook,tags,sourceIds,type='engine') => ({id,name,year:'current',type,lineage,parent,note,hook,tags,sourceIds,verifiedOn:checked});
const e = (source,target,type,note) => ({source,target,type,...(note?{note}:{})});

function enrich(file, expansion){
  const filePath = path.join(root,'data','lineages',file);
  const data = JSON.parse(fs.readFileSync(filePath,'utf8').replace(/^\uFEFF/,''));
  data.sources ||= []; data.nodes ||= []; data.edges ||= [];
  const sourceIds = new Set(data.sources.map(x=>x.id));
  for(const item of expansion.sources||[]) if(!sourceIds.has(item.id)){ data.sources.push(item); sourceIds.add(item.id); }
  const nodeIds = new Set(data.nodes.map(x=>x.id));
  for(const item of expansion.nodes||[]) if(!nodeIds.has(item.id)){ data.nodes.push(item); nodeIds.add(item.id); }
  const edgeIds = new Set(data.edges.map(x=>`${x.source}|${x.target}|${x.type||''}`));
  for(const item of expansion.edges||[]){ const id=`${item.source}|${item.target}|${item.type||''}`; if(!edgeIds.has(id)){ data.edges.push(item); edgeIds.add(id); } }
  fs.writeFileSync(filePath,JSON.stringify(data,null,2)+'\n');
  console.log(`enriched ${data.id}: ${data.nodes.length} nodes, ${data.edges.length} edges, ${data.sources.length} sources`);
}

